package com.tracker.entity;
import com.fasterxml.jackson.annotation.JsonIgnore; import jakarta.persistence.*; import jakarta.validation.constraints.*; import lombok.*; import java.time.*;
@Entity @Table(name="workshops") @Getter @Setter @NoArgsConstructor
public class Workshop { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @NotBlank @Size(max=180) private String title; @Size(max=3000) private String description; @Size(max=150) private String instructor; @Size(max=100) private String category; @NotNull private LocalDateTime startAt; @NotNull private LocalDateTime endAt; @Size(max=300) private String venue; @Size(max=300) private String meetingLink; private LocalDateTime registrationDeadline; @Min(1) private Integer capacity; @Size(max=30) private String status="DRAFT"; @ManyToOne(optional=false) @JoinColumn(name="faculty_id") @JsonIgnore private User faculty; }
